-- Luis 2026-11-13 15:52 UTC: Oleiro CGI text only; exact content before-images below support reviewed recovery.
BEGIN;
DO $cgi$ DECLARE before_hashes jsonb; blocks_before jsonb; q jsonb; d jsonb; n integer; BEGIN
IF public.pm_project_b1_active() THEN RAISE EXCEPTION 'B1 must remain OFF'; END IF;
SELECT to_jsonb(x) INTO q FROM public.fee_proposals x WHERE id='d73deb33-a0f9-41bb-ad4d-637cd5d159b6' FOR UPDATE;
SELECT to_jsonb(x) INTO d FROM public.psa_proposals x WHERE id='84e54031-64db-41d8-aa30-b22d882a6017' FOR UPDATE;
IF q->>'quote_status'<>'draft' OR d->>'status'<>'draft' OR (q->>'work_revision_ordinal')::int<>0 OR (d->>'work_revision_ordinal')::int<>0 THEN RAISE EXCEPTION 'Expected Rev00 Draft'; END IF;
before_hashes := public.crm_work_protected_hashes()-'psa_proposal_blocks';
SELECT jsonb_agg(to_jsonb(b) ORDER BY id) INTO blocks_before FROM public.psa_proposal_blocks b WHERE id NOT IN ('d6c5bb08-ce52-4e08-815f-46ea4c6bf4db','c86dcb13-3ba9-414b-9eac-359b0a165f6a');
-- Before content d6c5bb08-ce52-4e08-815f-46ea4c6bf4db: {"client_info": "Topographic survey of the plot\nBudget indications, if available at this stage\nAny existing drawings and documentation provided by the Client\nObjectives and key features of the project\n", "client_info_visible": false, "deliverables": "Plantas, cortes e alçados do estudo prévio.\nQuadro de áreas e de unidades de alojamento.\nMemória descritiva sumária.", "headingLevel": "h1", "html": "<p></p>", "key_activities_html": "<ul><li><p>Estudos do layout definitivo dos vários pisos e das unidades de alojamento;</p></li><li><p>Estudos de cortes e alçados;</p></li><li><p>Estudos de volumetria;</p></li><li><p>Estudos de materiais exteriores a usar;</p></li><li><p>Cálculo de áreas, cérceas e índices a cumprir;</p></li><li><p>Verificação preliminar dos requisitos de classificação aplicáveis aos apartamentos turísticos.</p></li></ul><p></p>", "key_activities_text": "\n\n\n\nEstudos do layout definitivo dos vários pisos e das unidades de alojamento;\n\n\n\nEstudos de cortes e alçados;\n\n\n\nEstudos de volumetria;\n\n\n\nEstudos de materiais exteriores a usar;\n\n\n\nCálculo de áreas, cérceas e índices a cumprir;\n\n\n\nVerificação preliminar dos requisitos de classificação aplicáveis aos apartamentos turísticos.\n\n", "objective_html": "<p>Depois de definido e aprovado o Programa Base, vamos desenvolver os conceitos que foram definidos e apresentar soluções através de desenhos ou outros elementos que facilitem a sua compreensão do projeto, como a sua organização e a sua aparência final.</p><p>Iremos definir a globalidade da intervenção, de acordo com as suas pretensões para a otimização do edifício, dentro do contexto da legislação em vigor para o local, e estudar a melhor estratégia de encaminhar o processo para a obtenção da aprovação do licenciamento camarário.</p><p>É ainda nosso papel consultar os projetistas dos projetos de especialidades para, em conjunto com estes, estudar as soluções do ponto de vista técnico, construtivo e de custos.</p>", "objective_text": "Depois de definido e aprovado o Programa Base, vamos desenvolver os conceitos que foram definidos e apresentar soluções através de desenhos ou outros elementos que facilitem a sua compreensão do projeto, como a sua organização e a sua aparência final.\n\nIremos definir a globalidade da intervenção, de acordo com as suas pretensões para a otimização do edifício, dentro do contexto da legislação em vigor para o local, e estudar a melhor estratégia de encaminhar o processo para a obtenção da aprovação do licenciamento camarário.\n\nÉ ainda nosso papel consultar os projetistas dos projetos de especialidades para, em conjunto com estes, estudar as soluções do ponto de vista técnico, construtivo e de custos.", "resources_visible": true, "stage_approval_html": "<p>Prevemos ir ao encontro dos seus objetivos através da apresentação de uma proposta de estudo prévio, desenvolvida durante o tempo estimado e com os recursos previstos no planeamento apresentado.</p><p>A nossa equipa fará as necessárias afinações na proposta de estudo prévio de forma a obter a sua total satisfação, desde que estas estejam dentro do número de horas previsto na nossa proposta de honorários.</p>", "stage_approval_text": "Prevemos ir ao encontro dos seus objetivos através da apresentação de uma proposta de estudo prévio, desenvolvida durante o tempo estimado e com os recursos previstos no planeamento apresentado.\n\nA nossa equipa fará as necessárias afinações na proposta de estudo prévio de forma a obter a sua total satisfação, desde que estas estejam dentro do número de horas previsto na nossa proposta de honorários.", "text": ""}
UPDATE public.psa_proposal_blocks SET content_rich='{"client_info": "Topographic survey of the plot\nBudget indications, if available at this stage\nAny existing drawings and documentation provided by the Client\nObjectives and key features of the project\n", "client_info_visible": false, "deliverables": "Plantas, cortes e alçados do estudo prévio.\nQuadro de áreas e de unidades de alojamento.\nMemória descritiva sumária.\n6 imagens 3D (CGI) ilustrativas do conceito de arquitetura.", "headingLevel": "h1", "html": "<p></p>", "key_activities_html": "<ul><li><p>Estudos do layout definitivo dos vários pisos e das unidades de alojamento;</p></li><li><p>Estudos de cortes e alçados;</p></li><li><p>Estudos de volumetria;</p></li><li><p>Estudos de materiais exteriores a usar;</p></li><li><p>Cálculo de áreas, cérceas e índices a cumprir;</p></li><li><p>Verificação preliminar dos requisitos de classificação aplicáveis aos apartamentos turísticos.</p></li></ul><p></p>", "key_activities_text": "\n\n\n\nEstudos do layout definitivo dos vários pisos e das unidades de alojamento;\n\n\n\nEstudos de cortes e alçados;\n\n\n\nEstudos de volumetria;\n\n\n\nEstudos de materiais exteriores a usar;\n\n\n\nCálculo de áreas, cérceas e índices a cumprir;\n\n\n\nVerificação preliminar dos requisitos de classificação aplicáveis aos apartamentos turísticos.\n\n", "objective_html": "<p>Depois de definido e aprovado o Programa Base, vamos desenvolver os conceitos que foram definidos e apresentar soluções através de desenhos ou outros elementos que facilitem a sua compreensão do projeto, como a sua organização e a sua aparência final.</p><p>Iremos definir a globalidade da intervenção, de acordo com as suas pretensões para a otimização do edifício, dentro do contexto da legislação em vigor para o local, e estudar a melhor estratégia de encaminhar o processo para a obtenção da aprovação do licenciamento camarário.</p><p>É ainda nosso papel consultar os projetistas dos projetos de especialidades para, em conjunto com estes, estudar as soluções do ponto de vista técnico, construtivo e de custos.</p>", "objective_text": "Depois de definido e aprovado o Programa Base, vamos desenvolver os conceitos que foram definidos e apresentar soluções através de desenhos ou outros elementos que facilitem a sua compreensão do projeto, como a sua organização e a sua aparência final.\n\nIremos definir a globalidade da intervenção, de acordo com as suas pretensões para a otimização do edifício, dentro do contexto da legislação em vigor para o local, e estudar a melhor estratégia de encaminhar o processo para a obtenção da aprovação do licenciamento camarário.\n\nÉ ainda nosso papel consultar os projetistas dos projetos de especialidades para, em conjunto com estes, estudar as soluções do ponto de vista técnico, construtivo e de custos.", "resources_visible": true, "stage_approval_html": "<p>Prevemos ir ao encontro dos seus objetivos através da apresentação de uma proposta de estudo prévio, desenvolvida durante o tempo estimado e com os recursos previstos no planeamento apresentado.</p><p>A nossa equipa fará as necessárias afinações na proposta de estudo prévio de forma a obter a sua total satisfação, desde que estas estejam dentro do número de horas previsto na nossa proposta de honorários.</p>", "stage_approval_text": "Prevemos ir ao encontro dos seus objetivos através da apresentação de uma proposta de estudo prévio, desenvolvida durante o tempo estimado e com os recursos previstos no planeamento apresentado.\n\nA nossa equipa fará as necessárias afinações na proposta de estudo prévio de forma a obter a sua total satisfação, desde que estas estejam dentro do número de horas previsto na nossa proposta de honorários.", "text": ""}'::jsonb WHERE id='d6c5bb08-ce52-4e08-815f-46ea4c6bf4db' AND proposal_id='84e54031-64db-41d8-aa30-b22d882a6017' AND md5(content_rich::text)='1d800ee2bbf4d0b2014675a3b64adaf1';
GET DIAGNOSTICS n=ROW_COUNT; IF n<>1 THEN RAISE EXCEPTION 'CGI before-image mismatch d6c5bb08-ce52-4e08-815f-46ea4c6bf4db'; END IF;
-- Before content c86dcb13-3ba9-414b-9eac-359b0a165f6a: {"headingLevel": "h1", "html": "<p>Estão excluídos da proposta:</p><ul><li><p>IVA à taxa legal em vigor;</p></li><li><p>Despesas de deslocação, como viagens, alojamento, refeições e despesas diversas associadas, fora do concelho de Lisboa, que não estejam contempladas no capítulo da Assistência Técnica;</p></li><li><p>Todos os serviços especializados necessários ao desenvolvimento do projeto, como levantamentos topográficos e arquitetónicos, estudos geotécnicos e geológicos, etc.;</p></li><li><p>Taxas camarárias e taxas de outras entidades;</p></li><li><p>Projetos de especialidades e de paisagismo;</p></li><li><p>Preparação e lançamento de concurso de empreitadas;</p></li><li><p>Direção técnica da obra, administração da obra, coordenação e fiscalização da obra;</p></li><li><p>Elaboração de desenhos de preparação de obra;</p></li><li><p>Maquetes profissionais;</p></li><li><p>Imagens 3D;</p></li><li><p>Projeto de decoração de interiores e de mobiliário, equipamento e decoração (FF&amp;E), salvo se contratado como serviço opcional;</p></li><li><p>Projetos especiais (cozinhas técnicas, piscinas e spa);</p></li><li><p>Pedidos ou negociações para a obtenção de financiamentos (privados ou corporate);</p></li><li><p>Processo de classificação do empreendimento turístico junto do Turismo de Portugal após a conclusão da obra, e registo ou autorização de exploração;</p></li><li><p>Certificação energética e acústica.</p></li></ul><p></p>", "text": "Estão excluídos da proposta:\n\n\n\n\n\nIVA à taxa legal em vigor;\n\n\n\nDespesas de deslocação, como viagens, alojamento, refeições e despesas diversas associadas, fora do concelho de Lisboa, que não estejam contempladas no capítulo da Assistência Técnica;\n\n\n\nTodos os serviços especializados necessários ao desenvolvimento do projeto, como levantamentos topográficos e arquitetónicos, estudos geotécnicos e geológicos, etc.;\n\n\n\nTaxas camarárias e taxas de outras entidades;\n\n\n\nProjetos de especialidades e de paisagismo;\n\n\n\nPreparação e lançamento de concurso de empreitadas;\n\n\n\nDireção técnica da obra, administração da obra, coordenação e fiscalização da obra;\n\n\n\nElaboração de desenhos de preparação de obra;\n\n\n\nMaquetes profissionais;\n\n\n\nImagens 3D;\n\n\n\nProjeto de decoração de interiores e de mobiliário, equipamento e decoração (FF&E), salvo se contratado como serviço opcional;\n\n\n\nProjetos especiais (cozinhas técnicas, piscinas e spa);\n\n\n\nPedidos ou negociações para a obtenção de financiamentos (privados ou corporate);\n\n\n\nProcesso de classificação do empreendimento turístico junto do Turismo de Portugal após a conclusão da obra, e registo ou autorização de exploração;\n\n\n\nCertificação energética e acústica.\n\n"}
UPDATE public.psa_proposal_blocks SET content_rich='{"headingLevel": "h1", "html": "<p>Estão excluídos da proposta:</p><ul><li><p>IVA à taxa legal em vigor;</p></li><li><p>Despesas de deslocação, como viagens, alojamento, refeições e despesas diversas associadas, fora do concelho de Lisboa, que não estejam contempladas no capítulo da Assistência Técnica;</p></li><li><p>Todos os serviços especializados necessários ao desenvolvimento do projeto, como levantamentos topográficos e arquitetónicos, estudos geotécnicos e geológicos, etc.;</p></li><li><p>Taxas camarárias e taxas de outras entidades;</p></li><li><p>Projetos de especialidades e de paisagismo;</p></li><li><p>Preparação e lançamento de concurso de empreitadas;</p></li><li><p>Direção técnica da obra, administração da obra, coordenação e fiscalização da obra;</p></li><li><p>Elaboração de desenhos de preparação de obra;</p></li><li><p>Maquetes profissionais;</p></li><li><p>Imagens 3D para além das 6 incluídas no Estudo prévio;</p></li><li><p>Projeto de decoração de interiores e de mobiliário, equipamento e decoração (FF&amp;E), salvo se contratado como serviço opcional;</p></li><li><p>Projetos especiais (cozinhas técnicas, piscinas e spa);</p></li><li><p>Pedidos ou negociações para a obtenção de financiamentos (privados ou corporate);</p></li><li><p>Processo de classificação do empreendimento turístico junto do Turismo de Portugal após a conclusão da obra, e registo ou autorização de exploração;</p></li><li><p>Certificação energética e acústica.</p></li></ul><p></p>", "text": "Estão excluídos da proposta:\n\n\n\n\n\nIVA à taxa legal em vigor;\n\n\n\nDespesas de deslocação, como viagens, alojamento, refeições e despesas diversas associadas, fora do concelho de Lisboa, que não estejam contempladas no capítulo da Assistência Técnica;\n\n\n\nTodos os serviços especializados necessários ao desenvolvimento do projeto, como levantamentos topográficos e arquitetónicos, estudos geotécnicos e geológicos, etc.;\n\n\n\nTaxas camarárias e taxas de outras entidades;\n\n\n\nProjetos de especialidades e de paisagismo;\n\n\n\nPreparação e lançamento de concurso de empreitadas;\n\n\n\nDireção técnica da obra, administração da obra, coordenação e fiscalização da obra;\n\n\n\nElaboração de desenhos de preparação de obra;\n\n\n\nMaquetes profissionais;\n\n\n\nImagens 3D para além das 6 incluídas no Estudo prévio;\n\n\n\nProjeto de decoração de interiores e de mobiliário, equipamento e decoração (FF&E), salvo se contratado como serviço opcional;\n\n\n\nProjetos especiais (cozinhas técnicas, piscinas e spa);\n\n\n\nPedidos ou negociações para a obtenção de financiamentos (privados ou corporate);\n\n\n\nProcesso de classificação do empreendimento turístico junto do Turismo de Portugal após a conclusão da obra, e registo ou autorização de exploração;\n\n\n\nCertificação energética e acústica.\n\n"}'::jsonb WHERE id='c86dcb13-3ba9-414b-9eac-359b0a165f6a' AND proposal_id='84e54031-64db-41d8-aa30-b22d882a6017' AND md5(content_rich::text)='a2aece37b95651a9770ea493daae74af';
GET DIAGNOSTICS n=ROW_COUNT; IF n<>1 THEN RAISE EXCEPTION 'CGI before-image mismatch c86dcb13-3ba9-414b-9eac-359b0a165f6a'; END IF;
IF before_hashes IS DISTINCT FROM (public.crm_work_protected_hashes()-'psa_proposal_blocks') THEN RAISE EXCEPTION 'Protected data changed'; END IF;
IF blocks_before IS DISTINCT FROM (SELECT jsonb_agg(to_jsonb(b) ORDER BY id) FROM public.psa_proposal_blocks b WHERE id NOT IN ('d6c5bb08-ce52-4e08-815f-46ea4c6bf4db','c86dcb13-3ba9-414b-9eac-359b0a165f6a')) THEN RAISE EXCEPTION 'Other blocks changed'; END IF;
IF (SELECT sum(amount_value) FROM public.quote_payment_schedule_items WHERE quote_id='d73deb33-a0f9-41bb-ad4d-637cd5d159b6' AND direction='inflow')<>221300 THEN RAISE EXCEPTION 'Expected total 221300'; END IF;
END $cgi$;
COMMIT;
